import re as _re
def _inline(s):
 s=_re.sub(r'\[([^\]]+)\]\(([^)]+)\)',r'<a href="\2">\1</a>',s)
 s=_re.sub(r'\*\*([^*]+)\*\*',r'<b>\1</b>',s)
 s=_re.sub(r'`([^`]+)`',r'<code>\1</code>',s)
 return s
_rout=['<header><p class="tag">SOURCES</p><h1>教材来源与使用方式</h1></header><section class="panel">']
_inlist=False
for _line in (root/'RESOURCES.md').read_text(encoding='utf-8').splitlines():
 _l=_line.strip()
 if not _l or _l.startswith('# '):continue
 if _l.startswith('## '):
  if _inlist:_rout.append('</ul>');_inlist=False
  _rout.append(f'<h2>{_inline(_l[3:])}</h2>')
 elif _l.startswith('- '):
  if not _inlist:_rout.append('<ul>');_inlist=True
  _rout.append(f'<li>{_inline(_l[2:])}</li>')
 else:
  if _inlist:_rout.append('</ul>');_inlist=False
  _rout.append(f'<p>{_inline(_l)}</p>')
if _inlist:_rout.append('</ul>')
_rout.append('</section>')
